import { VAT_RATE } from './rates';

export interface TaxLine {
  label: string;
  amount: number;
}

export function computeTax(subtotal: number): number {
  if (subtotal <= 0) return 0;
  return subtotal * VAT_RATE;
}

export function taxLines(subtotal: number): TaxLine[] {
  const amount = computeTax(subtotal);
  return amount === 0 ? [] : [{ label: 'VAT', amount }];
}

export function taxPreview(id: string): { id: string; lines: TaxLine[] } {
  return { id, lines: taxLines(0) };
}

